			var removeNameArr = oldNameArr.splice(index, 1);
			if (isNewGroup) {
				var newNameArr = removeNameArr;
				var newIdArr = removeIdArr;
			} else {
				newNameArr = newData["servers"].split(",");
				newIdArr = newData["serverIds"].split(",");
				newNameArr = newNameArr.concat(removeNameArr);
				newIdArr = newIdArr.concat(removeIdArr);
			}
			oldData["servers"] = oldNameArr.join(",");
			oldData["serverIds"] = oldIdArr.join(",");
			newData["servers"] = newNameArr.join(",");
			newData["serverIds"] = newIdArr.join(",");
