		__proto.upload = function () {
			if (this.comb_server.getCurSelectServerId() == 0) {
				AlertView.show("错误", "没有选择服务器id");
				return;
			};
			var dArr = Mgr.gmOperateOldRebackMgr.getRidArr();
			var page = 20;
			var curIdx = 0;
			var len = dArr.length;
			while (curIdx < len) {
				var endIdx = Math.min(curIdx + page, len);
				var arr = dArr.slice(curIdx, endIdx);
				var data = {};
				data["serverId"] = this.comb_server.getCurSelectServerId();
				data["array"] = JSON.stringify(arr);
				Mgr.gmOperateOldRebackMgr.upload(data);
				curIdx = endIdx;
			}
			AlertView.show("提示", "设置成功！！");
		}

		__proto.clearRid = function () {
			if (this.dataGrid != null) {
				this.dataGrid.dataSource = DGData.fromJsonObject([], DataGridHeader, DataGridCell,
					["userId"], ["玩家账号"]);
				this.txt_total.text = "总导入角色账号数：0";
			}
		}

		__proto.listRender = function (cell) {
			var label = cell.getChildByName("rid");
			label.text = cell.dataSource;
		}

		__proto.onSelectFile = function (result) {
			this.onLoadOk(result);
		}

		__proto.onLoadOk = function (data) {
			var arr = data.split(/[\r\n]+/);
			var len = arr.length;
			var dataArr = [];
			var maxLen = 0;
			for (var i = 0; i < len; i++) {
				var str = arr[i];
				if (str && str.length != 0) {
					var arr1 = str.split(/[ \t]+/);
					var len1 = arr1.length;
					var o = {};
					o["userId"] = arr1[0];
					var day = 1;
					for (var j = 1; j < len1; j++) {
						var item = arr1[j];
						if (item && item.length > 0) {
							o[day++] = item;
						}
					}
					maxLen = Math.max(maxLen, day);
					dataArr.push(o);
				}
			}
			Mgr.gmOperateOldRebackMgr.setRidArr(dataArr);
			var headKeyArr = ["userId"];
			var headNameArr = ["玩家账号"];
			var wdArr = [250];
			var maxO = dataArr[0];
			for (var i = 1; i < maxLen; i++) {
				headKeyArr.push(i);
				headNameArr.push("第" + i + "天");
				wdArr.push(maxO[i].length * 10);
			};
			var dataGrd = DGData.fromJsonObject(dataArr, DataGridHeader, DataGridCell,
				headKeyArr, headNameArr);
			dataGrd.columnWidth = wdArr;
			this.dataGrid.dataSource = dataGrd;
			this.txt_total.text = "总导入角色账号数：" + dataArr.length;
		}

		__proto.onOpened = function () {
			Mgr.menu.showFileInput(this.c, this.fileSelectHandler);
		}

